      "DELETE FROM user_weekly_schedule WHERE user_id = 'e2e00053-0000-0000-0000-000000000053' AND planned_day = CURRENT_DATE::text;",
      "INSERT INTO user_weekly_schedule (user_id, week, week_day, session_name, planned_day, planned_day_utc, \"Completed\") VALUES ('e2e00053-0000-0000-0000-000000000053', 1, CASE EXTRACT(DOW FROM CURRENT_DATE) WHEN 0 THEN 'Domingo' WHEN 1 THEN 'Lunes' WHEN 2 THEN 'Martes' WHEN 3 THEN 'Miercoles' WHEN 4 THEN 'Jueves' WHEN 5 THEN 'Viernes' WHEN 6 THEN 'Sabado' END, 'Full Body A', CURRENT_DATE::text, CURRENT_DATE::timestamp AT TIME ZONE 'America/Bogota', false);"
    ]
  }
];

const sortedTests = testCases.sort((a, b) => a.order - b.order);
$execution.customData.set('startTime', new Date().toISOString());
$execution.customData.set('totalTests', String(sortedTests.length));
$execution.customData.set('testResults', '[]');
console.log(`\u{1F4CB} Tests cargados: ${sortedTests.map(t => t.id).join(' -> ')}`);
return sortedTests.map(tc => ({ json: tc }));

const testCase = $input.first().json;
console.log(`\n========================================`);
console.log(`\u{1F9EA} [${testCase.order}/${$execution.customData.get('totalTests')}] ${testCase.id} - ${testCase.name}`);
console.log(`   Categoria: ${testCase.category}`);
console.log(`   Prioridad: ${testCase.priority}`);
console.log(`========================================`);
return [{ json: testCase }];

const testCase = $('Pre-Test Log').first().json;
const whatsappInput = testCase.input[0];
return [{ json: whatsappInput }];

const testCase = $('Pre-Test Log').first().json;
const workflowResult = $input.first().json;
let output = '';
try {
  if (workflowResult.output) output = workflowResult.output;
  else if (workflowResult.text) output = workflowResult.text;
  else if (typeof workflowResult === 'string') output = workflowResult;
  else {
    const findOutput = (obj) => {
      if (!obj || typeof obj !== 'object') return '';
      if (obj.output) return obj.output;
      if (obj.text) return obj.text;
      for (const key of Object.keys(obj)) {
        const found = findOutput(obj[key]);
        if (found) return found;
      }
      return '';
    };
    output = findOutput(workflowResult);
  }
} catch (e) { output = ''; }
let passed = false;
let error = null;
try {
  const rule = testCase.metrics.rule;
  passed = eval(rule);
} catch (e) { error = e.message; passed = false; }
const result = {
  order: testCase.order, testId: testCase.id, testName: testCase.name,
  category: testCase.category, priority: testCase.priority, passed,
  output: output ? output.substring(0, 500) : '(empty)',
  expectedRule: testCase.metrics.rule, ruleDescription: testCase.metrics.description,
  error, executedAt: new Date().toISOString()
};
let allResults = [];
try { const existing = $execution.customData.get('testResults'); if (existing) allResults = JSON.parse(existing); } catch(e) {}
allResults.push(result);
$execution.customData.set('testResults', JSON.stringify(allResults));
console.log(`${passed ? '\u2705 PASSED' : '\u274C FAILED'}: [${testCase.order}] ${testCase.id} - ${testCase.name}`);
return [{ json: result }];

const testCase = $('Pre-Test Log').first().json;
$execution.customData.set('turnResults', '[]');
console.log(`\n\u{1F504} Iniciando test multi-turno: ${testCase.turns.length} turnos`);
return testCase.turns.map((turn, index) => ({ json: { turnIndex: index, ...turn } }));

const testCase = $('Pre-Test Log').first().json;
const currentTurn = $input.first().json;
const phone = testCase.input[0].contacts[0].wa_id;
const name = testCase.input[0].contacts[0].profile.name;
console.log(`   \u{1F4E4} Turn ${currentTurn.turn}: "${currentTurn.message.substring(0, 50)}..."`);
return [{
  json: {
    messaging_product: "whatsapp",
    metadata: { display_phone_number: "550000000000", phone_number_id: "914510145083991" },
    contacts: [{ profile: { name }, wa_id: phone }],
    messages: [{
      from: phone,
      id: `wamid.E2E-${testCase.id}-TURN${currentTurn.turn}`,
      timestamp: String(Math.floor(Date.now() / 1000)),
      text: { body: currentTurn.message },
      type: "text"
    }],
    field: "messages"
  }
}];

const testCase = $('Pre-Test Log').first().json;
const buildTurnInput = $('Build Turn Input').first().json;
const workflowResult = $input.first().json;
const currentMessage = buildTurnInput.messages[0].text.body;
const turn = testCase.turns.find(t => t.message === currentMessage);
if (!turn) throw new Error(`Turn not found for message: ${currentMessage}`);
let output = '';
try {
  if (workflowResult.output) output = workflowResult.output;
  else if (workflowResult.text) output = workflowResult.text;
  else if (typeof workflowResult === 'string') output = workflowResult;
  else {
    const findOutput = (obj) => {
      if (!obj || typeof obj !== 'object') return '';
      if (obj.output) return obj.output;
      if (obj.text) return obj.text;
      for (const key of Object.keys(obj)) {
        const found = findOutput(obj[key]);
        if (found) return found;
      }
      return '';
    };
    output = findOutput(workflowResult);
  }
} catch (e) { output = ''; }
let whatsappSent = false;
if (!output && workflowResult.messaging_product === 'whatsapp' && Array.isArray(workflowResult.messages)) {
  whatsappSent = true;
  output = '[WhatsApp message sent: ' + (workflowResult.messages[0] && workflowResult.messages[0].id || 'unknown') + ']';
  console.log('   Detected WhatsApp API response - message was sent successfully');
}
const outputLower = output.toLowerCase();
const passed = turn.expectContains.some(keyword => outputLower.includes(keyword.toLowerCase())) || whatsappSent;
const emoji = passed ? '\u2705' : '\u274C';
console.log(`   ${emoji} Turn ${turn.turn}: ${passed ? 'PASSED' : 'FAILED'}`);
if (!passed) {
  console.log(`      Expected one of: ${turn.expectContains.join(', ')}`);
  console.log(`      Got: ${output.substring(0, 100)}...`);
}
const turnResult = { turn: turn.turn, message: turn.message, passed, output: output.substring(0, 300), expected: turn.expectContains };
$execution.customData.set('turnResult_' + turn.turn, JSON.stringify(turnResult));
return [{ json: { turn: turn.turn, passed, output: output.substring(0, 300) } }];

const testCase = $('Pre-Test Log').first().json;
let turnResults = [];
for (let i = 1; i <= testCase.turns.length; i++) {
  try {
    const data = $execution.customData.get('turnResult_' + i);
    if (data) turnResults.push(JSON.parse(data));
  } catch(e) {
    console.log('Could not read turnResult_' + i + ': ' + e.message);
  }
}
if (turnResults.length === 0 && testCase.turns.length > 0) {
  console.log('WARNING: No turn results captured for ' + testCase.turns.length + ' expected turns');
  turnResults = testCase.turns.map(t => ({
    turn: t.turn, message: t.message, passed: false,
    output: '[Turn result not captured]', expected: t.expectContains
  }));
}
const dbResults = $input.all();
const verification = testCase.verification;
let dbPassed = true;
let dbDetails = [];
if (verification && verification.queries) {
  verification.queries.forEach((query, idx) => {
    const result = dbResults[idx];
    let actualValue = 0;
    if (result && result.json) {
      actualValue = result.json.cnt || result.json.count || Object.values(result.json)[0] || 0;
    }
    const queryPassed = Number(actualValue) >= query.expected;
    dbPassed = dbPassed && queryPassed;
    dbDetails.push({ query: query.sql.substring(0, 50) + '...', expected: query.expected, actual: actualValue, passed: queryPassed });
    const emoji = queryPassed ? '\u2705' : '\u274C';
    console.log(`   ${emoji} DB Check ${idx + 1}: expected ${query.expected}, got ${actualValue}`);
  });
}
const allTurnsPassed = turnResults.every(t => t.passed);
const overallPassed = allTurnsPassed && dbPassed;
const passedTurns = turnResults.filter(t => t.passed).length;
const totalTurns = turnResults.length;
console.log(`\n\u{1F4CA} Resultado Multi-Turn:`);
console.log(`   Turnos: ${passedTurns}/${totalTurns}`);
console.log(`   DB Verification: ${dbPassed ? 'PASSED' : 'FAILED'}`);
console.log(`   Overall: ${overallPassed ? '\u2705 PASSED' : '\u274C FAILED'}`);
const result = {
  testId: testCase.id, testName: testCase.name, order: testCase.order, category: testCase.category,
  priority: testCase.priority, passed: overallPassed,
  output: `Turns: ${passedTurns}/${totalTurns} passed. DB: ${dbPassed ? 'OK' : 'FAIL'}`,
  expectedRule: testCase.metrics.rule, ruleDescription: testCase.metrics.description,
  error: overallPassed ? null : `Failed turns: ${turnResults.filter(t => !t.passed).map(t => t.turn).join(', ')}`,
  executedAt: new Date().toISOString(),
  details: { turns: turnResults, dbVerification: dbDetails }
};
let allResults = [];
try { const existing = $execution.customData.get('testResults'); if (existing) allResults = JSON.parse(existing); } catch(e) {}
allResults.push(result);
$execution.customData.set('testResults', JSON.stringify(allResults));
return [{ json: result }];

let results = [];
if (items && items.length > 0 && items[0].json && Array.isArray(items[0].json.results)) {
  results = items[0].json.results;
} else if (items && items.length > 0 && Array.isArray(items[0].json)) {
  results = items[0].json;
}
const total = results.length;
const passed = results.filter(r => r.passed);
const failed = results.filter(r => !r.passed);
const passRateRaw = total > 0 ? (passed.length / total) * 100 : 0;
const passRate = passRateRaw % 1 === 0 ? passRateRaw.toFixed(0) : passRateRaw.toFixed(1);
const byCategory = results.reduce((acc, curr) => {
  const cat = curr.category || 'UNCATEGORIZED';
  if (!acc[cat]) acc[cat] = { total: 0, passed: 0, failed: 0 };
  acc[cat].total++;
  curr.passed ? acc[cat].passed++ : acc[cat].failed++;
  return acc;
}, {});
let statusEmoji = failed.length === 0 ? '\u2705' : '\u274C';
if (total === 0) statusEmoji = '\u26A0\uFE0F';
let mdReport = `*\u{1F4CA} Test Report - Mesocycle Renewal*\n`;
mdReport += `\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\n`;
mdReport += `*Status:* ${statusEmoji} ${failed.length === 0 ? 'PASS' : 'FAIL'}\n`;
mdReport += `*Score:* ${passRate}% (${passed.length}/${total})\n`;
mdReport += `*Time:* ${new Date().toLocaleString('es-CO')}\n\n`;
mdReport += `*\u{1F4C2} Categor\u00EDas:*\n`;
Object.keys(byCategory).forEach(cat => {
  const c = byCategory[cat];
  const icon = c.failed === 0 ? '\u2714' : '\u2757';
  mdReport += `${icon} ${cat}: ${c.passed}/${c.total}\n`;
});
if (failed.length > 0) {
  mdReport += `\n*\u{1F6A8} Fallos Detectados:*\n`;
  failed.forEach(f => {
    mdReport += `\u2022 *[${f.priority}] ${f.testName}*\n`;
    mdReport += `  _Exp:_ ${f.ruleDescription}\n`;
    const cleanOutput = (f.output || 'null').replace(/\n/g, ' ').substring(0, 80);
    mdReport += `  _Got:_ ${cleanOutput}...\n`;
  });
}
console.log('\n\u2554\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2557');
console.log(`\u2551 STATUS: ${statusEmoji}  RATE: ${passRate}% (${passed.length}/${total})`.padEnd(47) + '\u2551');
console.log('\u2560\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2563');
Object.keys(byCategory).forEach(cat => {
  const c = byCategory[cat];
  const bar = c.failed === 0 ? 'OK' : 'FAIL';
  console.log(`\u2551 ${cat.padEnd(20)}: ${c.passed}/${c.total} ${bar.padStart(13)} \u2551`);
});
console.log('\u255A\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u255D');
return [{
  json: {
    meta: { timestamp: new Date().toISOString(), totalTests: total, success: failed.length === 0 },
    markdownReport: mdReport,
    stats: { passed: passed.length, failed: failed.length, rate: parseFloat(passRate), byCategory },
    failures: failed.map(r => ({ testId: r.testId, name: r.testName, category: r.category, reason: r.ruleDescription, output: r.output }))
  }
}];
